1	/* ============================================================================
2	   scrollcraft: a scroll-driven interaction runtime
3	   ----------------------------------------------------------------------------
4	   Vanilla JS. Zero dependencies. Zero DOM generation.
5	
6	   The engine does NOT build your page. You author real, semantic HTML and mark
7	   it up with data-sc-* attributes; the engine reads them and drives them from a
8	   single scroll value on a single rAF loop. That is deliberate: a runtime that
9	   generates its own DOM from a config object makes every site it touches look
10	   identical, which is the failure mode this replaces.
11	
12	   ---------------------------------------------------------------------------
13	   ACTS: the unit of scroll time
14	   ---------------------------------------------------------------------------
15	     <section data-sc-act="pin" data-sc-span="2.5"> ... </section>
16	
17	     data-sc-act   scrub | pin | pan | flow   (default: flow)
18	     data-sc-clip-map="travel" opts a pinned act OUT of full-life clip mapping.
19	                   By DEFAULT a scrub clip is mapped across the stage's entire
20	                   on-screen life, not across its pinned travel, because a pinned
21	                   stage is visible for a viewport BEFORE the pin begins (sliding
22	                   up into view) and a viewport AFTER it ends (sliding off the
23	                   top). Mapped to pinned travel, the clip sits on its first
24	                   frame through the whole entry and its last frame through the
25	                   whole exit: the reader watches a still photograph while the
26	                   page moves. Pair it with data-sc-dwell, which moves quickly at
27	                   the edges and settles in the middle, so the fast motion lands
28	                   on the two slides and the settle lands inside the pin where
29	                   the copy is. data-sc-runout is accepted and ignored; it named
30	                   the old opt-in for the exit half of this.
31	     data-sc-span  viewport-heights of scroll this act owns. Pinned devices only
32	                   (scrub/pin/pan). Default 1.5. The engine sets the outer
33	                   height and sticks the first .sc-stage / [data-sc-stage] child.
34	
35	     Every act exposes a normalized progress p (0..1):
36	       pinned  p = (y - top) / (height - vh)
37	       flow    p = (y + vh - top) / (height + vh)
38	     and publishes it as --sc-p on the act element, so CSS can read it too.
39	
40	   ---------------------------------------------------------------------------
41	   DEVICES: what p drives
42	   ---------------------------------------------------------------------------
43	     data-sc-scrub            on <video>. p scrubs currentTime. Blob-loaded, so
44	                              it seeks without needing HTTP range support.
45	     data-sc-sequence="a/{i}.webp:120:1"
46	                              on <canvas>. p scrubs an image sequence
47	                              (path template : frameCount : startIndex).
48	     data-sc-pan="0.6"        on a wide rail inside data-sc-act="pan". p drives
49	                              horizontal travel. Value = extra travel multiplier.
50	     data-sc-parallax="-0.2"  translateY by rate * act-progress * viewport.
51	                              Negative = moves up faster than scroll (recedes).
52	     data-sc-cue="0.1 0.5"    opacity/rise keyed to p. One value = enter+hold.
53	                              Two = enter..leave. Add a third for the hold point.
54	     data-sc-kinetic="lines"  lines | words | chars. Splits the element and
55	                              staggers its reveal across the cue window.
56	     data-sc-reveal="up"      up | down | left | right | iris. clip-path wipe.
57	     data-sc-count="0 4200"   number bloom across the cue window. Outside any
58	                              act it ticks up once on entry instead, over
59	                              data-sc-count-ms (default 1400).
60	     data-sc-in               flow-section reveal, fires once on entry via
61	                              IntersectionObserver (cheaper, and content that
62	                              re-hides on scroll-up is a defect, not an effect).
63	                              data-sc-stagger="60" on the parent staggers kids.
64	     data-sc-drift="#07090c"  page background interpolates toward this colour
65	                              while the act is on screen.
66	
67	   ---------------------------------------------------------------------------
68	   WORLDFLIGHT: the page mode for one continuous flight
69	   ---------------------------------------------------------------------------
70	     <div data-sc-mode="worldflight" data-sc-seam="0.12">
71	       <div data-sc-world>
72	         <div data-sc-segment data-sc-w="1.4" data-sc-linger="0.3"
73	              data-sc-waypoint="Approach">
74	           <img class="sc-world__poster" src="p1.webp" alt="">
75	           <video data-sc-src="leg1.mp4" data-sc-src-mobile="leg1-m.mp4"></video>
76	         </div>
77	         ... more segments, in flight order ...
78	       </div>
79	       <div data-sc-world-copy>
80	         <div class="sc-world__scrim sc-scrim sc-scrim--band"></div>
81	         <div data-sc-copy data-sc-window="hero"> ... </div>
82	         <div data-sc-copy data-sc-window="0.34 0.56"> ... </div>
83	         <div data-sc-copy data-sc-window="finale"> ... </div>
84	       </div>
85	       <div data-sc-spacer aria-hidden="true"></div>
86	     </div>
87	
88	   Acts cut the page into pinned blocks, which is the right shape for a page of
89	   chapters and the wrong shape for one continuous camera move: the reader hits
90	   the end of an act, the stage unsticks, a static page slides past, and the next
91	   act starts the whole thing again. Worldflight removes the seams by removing
92	   the blocks. There is ONE fixed stage for the entire page. The only element in
93	   document flow is a spacer, whose height the engine sets to the sum of the
94	   segment weights plus one viewport so the last flight can finish. Scroll drives
95	   the film timeline and the overlay opacity. Nothing else moves.
96	
97	     data-sc-w        viewport-heights this segment owns. Default 1.3.
98	     data-sc-linger   dwell remap for this leg only (see lingerEase). Max 0.6.
99	     data-sc-seam     crossfade band, in viewport-heights of scroll. Default 0.12.
100	     data-sc-waypoint label published on --sc-seg / the sc:waypoint event, so a
101	                      page can draw its own route rail. The engine draws none.
102	     data-sc-window   on a copy block: "hero" | "finale" | "from to [in [out]]"
103	                      as fractions of the WHOLE track.
104	
105	   Every clip stays mounted for the life of the page. Segments crossfade by
106	   opacity over the seam band; nothing ever swaps a src, because a src swap is a
107	   black frame and a black frame is the cut this mode exists to avoid.
108	
109	   ---------------------------------------------------------------------------
110	   POINTER: interactivity that isn't scroll
111	   ---------------------------------------------------------------------------
112	     data-sc-tilt="8"         3D tilt toward the pointer, spring-damped, degrees.
113	     data-sc-magnet="0.35"    element drifts toward the pointer inside its bounds.
114	     data-sc-spotlight        publishes --sc-mx/--sc-my (0..1) for a light that
115	                              follows the pointer across the surface.
116	   All three are gated to (hover: hover) and (pointer: fine) and disabled under
117	   prefers-reduced-motion. Touch never fires them.
118	
119	   ---------------------------------------------------------------------------
120	   REDUCED MOTION
121	   ---------------------------------------------------------------------------
122	   Fewer and gentler, not zero. Cues still fade (comprehension survives), but
123	   translation collapses, video clips are never fetched (the poster holds), and
124	   pointer devices are inert. A worldflight still tells its whole story: the
125	   posters cross-dissolve through the same seams and the same copy windows.
126	
127	   ---------------------------------------------------------------------------
128	   THE PLAYHEAD
129	   ---------------------------------------------------------------------------
130	   Every scrub clip on the page, act or worldflight, is driven by one smoothed
131	   playhead. Scroll only ever writes a TARGET; a standalone rAF loop walks the
132	   current time toward it at a fixed fraction per frame (data-sc-lerp, default
133	   0.18; 1.0 under reduced motion, which is no smoothing at all). Writes are
134	   gated by a deadband and skipped while the decoder is still seeking. Without
135	   the smoothing a trackpad flick reads as a stutter, because wheel events do
136	   not arrive at a constant rate and a 1:1 write reproduces every gap in them.
137	   ========================================================================== */
138	
139	(function (global) {
140	  'use strict';
141	
142	  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
143	  var fineMQ = matchMedia('(hover: hover) and (pointer: fine)');
144	  var smallMQ = matchMedia('(max-width: 860px)');
145	  var coarse = matchMedia('(hover: none) and (pointer: coarse)').matches;
146	  var isMobile = function () { return coarse || smallMQ.matches; };
147	
148	  var clamp = function (x, a, b) { return x < a ? a : x > b ? b : x; };
149	  var clamp01 = function (x) { return clamp(x, 0, 1); };
150	  var smooth = function (x) { x = clamp01(x); return x * x * (3 - 2 * x); };
151	  var lerp = function (a, b, t) { return a + (b - a) * t; };
152	
153	  // Monotone dwell remap. Settles the camera mid-act (where the copy peaks) and
154	  // moves quicker at the edges. f(0)=0 and f(1)=1 always, so seam frames between
155	  // consecutive clips are untouched and the chain stays invisible.
156	  function dwell(x, L) {
157	    if (!L) return x;
158	    L = clamp01(L);
159	    var c = x - 0.5;
160	    return (1 - L) * x + L * (4 * c * c * c + 0.5);
161	  }
162	
163	  // Same curve, capped harder, and used per worldflight segment. Above ~0.6 the
164	  // derivative at the midpoint gets low enough that the camera visibly stops
165	  // dead mid-leg, which reads as a stall rather than a hold. The endpoints are
166	  // fixed by construction: f(0)=0, f(1)=1, so the first and last frames of every
167	  // leg are still exactly the frames the seam law matched, and the chain between
168	  // legs stays invisible no matter how much dwell a leg asks for.
169	  function lingerEase(x, L) {
170	    if (!L) return x;
171	    L = clamp(L, 0, 0.6);
172	    var c = x - 0.5;
173	    return (1 - L) * x + L * (4 * c * c * c + 0.5);
174	  }
175	
176	  // The lerp is a mechanism, not a taste knob. It is exposed so a page whose
177	  // clips are unusually short (where 0.18 lags behind the pointer) can tighten
178	  // it, and it is never read as 0: a 0 lerp is a playhead that never moves.
179	  function lerpRate(el) {
180	    var v = parseFloat(el && el.getAttribute && el.getAttribute('data-sc-lerp'));
181	    return isNaN(v) || v <= 0 ? 0 : clamp(v, 0.02, 1);
182	  }
183	
184	  // ---- colour -------------------------------------------------------------
185	  function parseColor(str) {
186	    str = (str || '').trim();
187	    var m = str.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
188	    if (m) {
189	      var h = m[1];
190	      if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
191	      return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
192	    }
193	    m = str.match(/rgba?\(([^)]+)\)/i);
194	    if (m) {
195	      var p = m[1].split(/[,\s/]+/).filter(Boolean).map(parseFloat);
196	      return [p[0], p[1], p[2]];
197	    }
198	    return null;
199	  }
200	  function mixColor(a, b, t) {
201	    return 'rgb(' + Math.round(lerp(a[0], b[0], t)) + ',' +
202	                    Math.round(lerp(a[1], b[1], t)) + ',' +
203	                    Math.round(lerp(a[2], b[2], t)) + ')';
204	  }
205	
206	  // ---- text splitting -----------------------------------------------------
207	  // Wraps each unit in a masked span so the reveal can slide from behind a clean
208	  // edge instead of just fading. Lines are measured after layout, so this must
209	  // run once fonts are ready or the line boxes are wrong.
210	  function splitText(el, mode) {
211	    if (el.__scSplit) return el.__scSplit;
212	    var text = el.textContent;
213	    var units = [];
214	
215	    if (mode === 'chars' || mode === 'words') {
216	      var parts = mode === 'chars' ? Array.from(text) : text.split(/(\s+)/);
217	      el.textContent = '';
218	      parts.forEach(function (t) {
219	        if (/^\s+$/.test(t)) { el.appendChild(document.createTextNode(t)); return; }
220	        var mask = document.createElement('span');
221	        mask.className = 'sc-split';
222	        var inner = document.createElement('span');
223	        inner.className = 'sc-split__i';
224	        inner.textContent = t;
225	        mask.appendChild(inner);
226	        el.appendChild(mask);
227	        units.push(inner);
228	      });
229	    } else {
230	      // lines: wrap every word, measure offsetTop, regroup words into line spans
231	      var words = text.split(/\s+/).filter(Boolean);
232	      el.textContent = '';
233	      var probes = words.map(function (w, i) {
234	        var s = document.createElement('span');
235	        s.textContent = w;
236	        el.appendChild(s);
237	        if (i < words.length - 1) el.appendChild(document.createTextNode(' '));
238	        return s;
239	      });
240	      var lines = [], cur = null, lastTop = null;
241	      probes.forEach(function (s) {
242	        var top = s.offsetTop;
243	        if (lastTop === null || Math.abs(top - lastTop) > 1) { cur = []; lines.push(cur); lastTop = top; }
244	        cur.push(s.textContent);
245	      });
246	      el.textContent = '';
247	      lines.forEach(function (words, li) {
248	        var mask = document.createElement('span');
249	        mask.className = 'sc-split sc-split--line';
250	        var inner = document.createElement('span');
251	        inner.className = 'sc-split__i';
252	        inner.textContent = words.join(' ');
253	        mask.appendChild(inner);
254	        el.appendChild(mask);
255	        // Whitespace between the line spans. Without it the line boxes abut in
256	        // the text layer, so selecting and copying the heading yields
257	        // "even whenbreakfast" and a screen reader hears the same.
258	        if (li < lines.length - 1) el.appendChild(document.createTextNode(' '));
259	        units.push(inner);
260	      });
261	    }
262	    el.classList.add('sc-is-split');
263	    el.__scSplit = units;
264	    return units;
265	  }
266	
267	  // ---- number formatting --------------------------------------------------
268	  function formatNum(v, template) {
269	    var decimals = 0;
270	    var dot = template.indexOf('.');
271	    if (dot > -1) decimals = template.length - dot - 1;
272	    var s = v.toFixed(decimals);
273	    if (/,/.test(template) || Math.abs(v) >= 10000) {
274	      var bits = s.split('.');
275	      bits[0] = bits[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
276	      s = bits.join('.');
277	    }
278	    return s;
279	  }
280	
281	  // =========================================================================
282	  function mount(root, opts) {
283	    root = typeof root === 'string' ? document.querySelector(root) : (root || document);
284	    opts = opts || {};
285	
286	    var acts = [];
287	    var worlds = [];
288	    var drifts = [];
289	    var playheads = [];
290	    var scrollEls = [];
291	    var vh = innerHeight, vw = innerWidth;
292	    var y = 0, needsLayout = true;
293	    var progressBar = root.querySelector('[data-sc-progress]');
294	    var docEl = document.documentElement;
295	
296	    // One rate for the page, overridable per clip. Read from the mount root, the
297	    // document element, or the option bag, in that order.
298	    var LERP = lerpRate(root.nodeType === 1 ? root : null) ||
299	               lerpRate(docEl) ||
300	               (opts.lerp > 0 ? clamp(opts.lerp, 0.02, 1) : 0) ||
301	               0.18;
302	
303	    // Every scrub clip on the page lives here, whatever drives it. tick() walks
304	    // this one list, so an act clip and a worldflight leg get the same playhead.
305	    function makeClip(v, host) {
306	      var rec = {
307	        el: v, host: host || v,
308	        ready: false, loading: false, painted: false,
309	        cur: 0, target: 0, live: false, stuckAt: 0,
310	        lerp: lerpRate(v) || LERP
311	      };
312	      v.muted = true; v.playsInline = true; v.preload = 'none';
313	      v.setAttribute('muted', ''); v.setAttribute('playsinline', '');
314	      playheads.push(rec);
315	      return rec;
316	    }
317	
318	    // ---- collect acts -----------------------------------------------------
319	    Array.prototype.forEach.call(root.querySelectorAll('[data-sc-act]'), function (el) {
320	      var device = el.getAttribute('data-sc-act') || 'flow';
321	      var pinned = device === 'scrub' || device === 'pin' || device === 'pan';
322	      var act = {
323	        el: el,
324	        device: device,
325	        pinned: pinned,
326	        span: parseFloat(el.getAttribute('data-sc-span')) || (pinned ? 1.5 : 0),
327	        dwell: parseFloat(el.getAttribute('data-sc-dwell')) || 0,
328	        clipTravel: pinned && el.getAttribute('data-sc-clip-map') === 'travel',
329	        p: 0, raw: 0, top: 0, height: 0, live: false,
330	        cues: [], parallax: [], reveals: [], counts: [],
331	        video: null, seq: null, rail: null
332	      };
333	
334	      if (pinned) {
335	        act.stage = el.querySelector('[data-sc-stage]') || el.querySelector('.sc-stage');
336	        if (act.stage) act.stage.classList.add('sc-stage');
337	        el.classList.add('sc-act--pinned');
338	      }
339	
340	      // scrub video
341	      var v = el.querySelector('video[data-sc-scrub]');
342	      if (v) act.video = makeClip(v, el);
343	
344	      // image sequence
345	      var cv = el.querySelector('canvas[data-sc-sequence]');
346	      if (cv) {
347	        var spec = cv.getAttribute('data-sc-sequence').split(':');
348	        act.seq = {
349	          el: cv, ctx: cv.getContext('2d', { alpha: false }),
350	          tpl: spec[0], count: parseInt(spec[1], 10) || 1, start: parseInt(spec[2], 10) || 0,
351	          frames: [], loaded: 0, drawn: -1
352	        };
353	      }
354	
355	      // horizontal rail
356	      act.rail = el.querySelector('[data-sc-pan]');
357	      if (act.rail) act.railExtra = parseFloat(act.rail.getAttribute('data-sc-pan')) || 0;
358	
359	      // cues
360	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-cue]'), function (c) {
361	        var nums = (c.getAttribute('data-sc-cue') || '').trim().split(/\s+/).map(parseFloat);
362	        // from [to [rampIn [rampOut]]]
363	        // rampIn/rampOut are fractions OF THE WINDOW, defaulting to 0.3 each.
364	        // That leaves a ~40% plateau at full opacity in the middle. Without a
365	        // plateau a cue is a triangle: it touches opacity 1 for a single
366	        // instant, so the reader has to stop on exactly the right pixel to see
367	        // the line at full strength, and every heading reads as slightly faded.
368	        var cue = {
369	          el: c,
370	          from: isNaN(nums[0]) ? 0 : nums[0],
371	          to: nums.length > 1 && !isNaN(nums[1]) ? nums[1] : null,
372	          rIn: nums.length > 2 && !isNaN(nums[2]) ? clamp01(nums[2]) : 0.3,
373	          rOut: nums.length > 3 && !isNaN(nums[3]) ? clamp01(nums[3]) : null,
374	          rise: parseFloat(c.getAttribute('data-sc-rise')),
375	          kinetic: c.getAttribute('data-sc-kinetic'),
376	          units: null, state: -1
377	        };
378	        if (cue.rOut === null) cue.rOut = (nums.length > 2 && !isNaN(nums[2])) ? 0.3 : 0.3;
379	        if (isNaN(cue.rise)) cue.rise = 1;
380	        act.cues.push(cue);
381	      });
382	
383	      // parallax
384	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-parallax]'), function (c) {
385	        act.parallax.push({ el: c, rate: parseFloat(c.getAttribute('data-sc-parallax')) || 0 });
386	      });
387	
388	      // reveals
389	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-reveal]'), function (c) {
390	        var nums = (c.getAttribute('data-sc-reveal-at') || '0 0.5').trim().split(/\s+/).map(parseFloat);
391	        act.reveals.push({ el: c, dir: c.getAttribute('data-sc-reveal') || 'up', from: nums[0] || 0, to: nums[1] || 0.5 });
392	      });
393	
394	      // counters
395	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-count]'), function (c) {
396	        var nums = (c.getAttribute('data-sc-count') || '').trim().split(/\s+/);
397	        var at = (c.getAttribute('data-sc-count-at') || '0.1 0.55').trim().split(/\s+/).map(parseFloat);
398	        // Strip separators before parsing so the author can write the target
399	        // exactly as it should render. Without this, "0 3,500" parses the target
400	        // as 3 (the comma stops parseFloat) and "0 3500" renders "3500", because
401	        // formatNum only adds separators above 10,000. So any real figure between
402	        // 1,000 and 9,999 could not be shown the way it is written everywhere
403	        // else on the page. The template still drives the formatting.
404	        var num = function (s) { return parseFloat(String(s).replace(/,/g, '')) || 0; };
405	        act.counts.push({
406	          el: c, a: num(nums[0]), b: num(nums[1]),
407	          tpl: nums[1] || '0', from: at[0], to: at[1], last: null
408	        });
409	      });
410	
411	      acts.push(act);
412	
413	      var d = el.getAttribute('data-sc-drift');
414	      if (d) { var rgb = parseColor(d); if (rgb) drifts.push({ act: act, rgb: rgb }); }
415	    });
416	
417	    // ---- collect worldflights --------------------------------------------
418	    Array.prototype.forEach.call(root.querySelectorAll('[data-sc-mode="worldflight"]'), function (el) {
419	      var W = {
420	        el: el,
421	        stage: el.querySelector('[data-sc-world]') || el.querySelector('.sc-world'),
422	        copyLayer: el.querySelector('[data-sc-world-copy]') || el.querySelector('.sc-world__copy'),
423	        spacer: el.querySelector('[data-sc-spacer]') || el.querySelector('.sc-world__spacer'),
424	        seam: 0, segs: [], copies: [], total: 0, top: 0, index: -1, checked: false
425	      };
426	      var seam = parseFloat(el.getAttribute('data-sc-seam'));
427	      // A seam wider than the shortest leg would have three clips dissolving at
428	      // once and no leg ever fully present. Cap it well under that.
429	      W.seam = isNaN(seam) || seam <= 0 ? 0.12 : clamp(seam, 0.02, 0.4);
430	      if (W.stage) W.stage.classList.add('sc-world');
431	      if (W.copyLayer) W.copyLayer.classList.add('sc-world__copy');
432	      if (W.spacer) W.spacer.classList.add('sc-world__spacer');
433	
434	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-segment]'), function (s) {
435	        var seg = {
436	          el: s,
437	          w: parseFloat(s.getAttribute('data-sc-w')) || 1.3,
438	          linger: clamp(parseFloat(s.getAttribute('data-sc-linger')) || 0, 0, 0.6),
439	          label: s.getAttribute('data-sc-waypoint') || '',
440	          poster: s.querySelector('[data-sc-poster]') || s.querySelector('.sc-world__poster') || s.querySelector('img'),
441	          c0: 0, c1: 0, local: 0, op: -1, z: -1, clip: null
442	        };
443	        s.classList.add('sc-world__seg');
444	        if (seg.poster) seg.poster.classList.add('sc-world__poster');
445	        var v = s.querySelector('video');
446	        if (v) {
447	          // Mark it as a scrub clip whether or not the author did. Everything
448	          // downstream, the stylesheet and the verification harness included,
449	          // finds scrub media by this attribute.
450	          v.setAttribute('data-sc-scrub', '');
451	          seg.clip = makeClip(v, s);
452	        }
453	        W.segs.push(seg);
454	      });
455	
456	      var run = 0;
457	      W.segs.forEach(function (s) { s.c0 = run; run += Math.max(s.w, 0.1); s.c1 = run; });
458	      W.total = Math.max(run, 0.001);
459	
460	      Array.prototype.forEach.call(el.querySelectorAll('[data-sc-copy]'), function (cEl) {
461	        var spec = (cEl.getAttribute('data-sc-window') || '').trim();
462	        var q = { el: cEl, from: 0, to: 1, rIn: 0.3, rOut: 0.3, state: -1 };
463	        var first = W.segs[0], last = W.segs[W.segs.length - 1];
