with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={'width':1440,'height':900})
    page = ctx.new_page()
    page.on('console', lambda m: print('[console]', m.type, m.text))
    page.on('pageerror', lambda e: print('[pageerror]', e))
