/* Alunix K1 Skymning — runda 2. Sex tokens + två typsnitt (scripts/scroll/NOTE.md).
   Aldrig restylad: .sc-stage, .sc-copy, .sc-scrim, [data-sc-*]. Allt annat härifrån. */

:root {
  --sc-canvas:      #0b1424;
  --sc-surface:     #121c30;
  --sc-ink:         #f4efe6;
  --sc-ink-soft:    #b9c0d0;
  --sc-accent:      #f2c46b;
  --sc-accent-ink:  #1c1408;

  --sc-font-display: "Newsreader", Georgia, serif;
  --sc-font-text:    "Schibsted Grotesk", system-ui, sans-serif;

  /* egna, ej motorns sex-plus-två: mörk ink för det vita klippet i akt 4 */
  --ink-on-white:      #17181b;
  --ink-soft-on-white: #5c5f68;
  --paper:             #ffffff;
}

html, body { overflow-x: clip; }

/* ------------------------------------------------------------- toppbar -- */
.topbar {
  position: fixed; inset: 0 0 auto 0; z-index: 80;
  display: flex; align-items: center; justify-content: space-between;
  padding: clamp(1rem, 3vw, 1.75rem) clamp(1.25rem, 4vw, 2.5rem);
  pointer-events: none;
}
.topbar::before {
  content: ""; position: absolute; inset: 0; height: 160%;
  background: linear-gradient(180deg, rgba(6,10,18,0.5), transparent);
  z-index: -1; opacity: 0.9; transition: opacity 300ms var(--sc-ease-out, ease);
}
.topbar.is-dim::before { opacity: 1; background: linear-gradient(180deg, rgba(4,6,10,0.72) 40%, transparent); }
.topbar__mark { pointer-events: auto; line-height: 0; }
.topbar__mark img { height: 20px; width: auto; filter: drop-shadow(0 1px 3px rgba(0,0,0,0.4)); }
.topbar__contact {
  pointer-events: auto;
  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
  color: var(--sc-ink); text-decoration: none;
  border-bottom: 1px solid color-mix(in oklab, var(--sc-ink) 40%, transparent);
}
.topbar__contact:hover { border-bottom-color: var(--sc-accent); color: var(--sc-accent); }
.topbar__label {
  font-family: var(--sc-font-text); font-size: var(--sc-t-xs);
  letter-spacing: var(--sc-track-wide); text-transform: uppercase;
  color: var(--sc-ink-soft); opacity: 0; white-space: nowrap;
  position: absolute; left: 50%; translate: -50% 0;
}
@media (max-width: 860px) { .topbar__label { display: none; } }

/* ------------------------------------------------------- reservläge/motion toggle -- */
.motion-only { display: none; }
html.motion .motion-only { display: block; }
html.motion .rm-only { display: none; }
.rm-only { display: block; }

/* ------------------------------------------------------------- akt 1-3 hero -- */
#hero [data-sc-stage] { background: var(--sc-canvas); }

.window-glow, .window-fill, .window-glass {
  position: absolute; left: 0; top: 0; width: 0; height: 0;
  opacity: 0; z-index: 2; pointer-events: none;
}
.window-glow {
  background: radial-gradient(closest-side, color-mix(in oklab, var(--sc-accent) 85%, white) 0%, color-mix(in oklab, var(--sc-accent) 40%, transparent) 60%, transparent 100%);
}
.window-fill { object-fit: cover; display: block; }
.window-glass { overflow: hidden; mix-blend-mode: multiply; }
.window-glass__canvas { width: 100%; height: 100%; display: block; }

.hero-copy {
  filter: blur(calc(min(var(--sc-p, 0), 0.3) * 46.67px));
}
.hero-title {
  font-weight: 300; font-size: clamp(2.2rem, 3.4rem + 1.6vw, 5.5rem);
  line-height: 1.05; letter-spacing: -0.01em; color: var(--sc-ink);
  max-width: 16ch;
}
.accent-u { text-decoration: underline; text-decoration-color: var(--sc-accent); text-decoration-thickness: 2px; text-underline-offset: 0.1em; }
.hero-sub { color: var(--sc-ink); opacity: 0.86; margin-top: var(--sc-4); font-size: var(--sc-t-lg); }

.site-names {
  position: absolute; left: var(--sc-gutter); bottom: clamp(1.25rem, 4vh, 2.5rem);
  z-index: 5; margin: 0;
  font-family: var(--sc-font-text); font-size: var(--sc-t-sm);
  letter-spacing: var(--sc-track-normal); color: var(--sc-ink-soft);
}
.site-names--static { position: static; margin-top: var(--sc-6); color: var(--sc-ink-soft); }

/* --------------------------------------------------------- akt 3 pin/ram -- */
.reveal-stage { background: #05070c; }
.reveal-frozen {
  position: absolute; inset: 0; z-index: 3; pointer-events: none;
  transform-origin: 50.3% 51.5%;
  transform: scale(calc(1 + (min(var(--sc-p, 0), 0.35) / 0.35) * 0.282));
  opacity: calc(1 - (min(var(--sc-p, 0), 0.35) / 0.35));
}
.reveal-frozen__photo, .reveal-frozen__horai { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.reveal-frozen__glass { position: absolute; inset: 0; mix-blend-mode: multiply; opacity: 0.4; background: linear-gradient(180deg, rgba(255,224,170,0.25), rgba(20,14,8,0.35)); }
.reveal-frame {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; z-index: 2;
  opacity: calc(min(var(--sc-p, 0), 0.35) / 0.35);
}

/* -------------------------------------------------------------- akt 4 exit -- */
.exit-stage { background: var(--sc-canvas); overflow: clip; }
.exit-sweep { position: absolute; inset: 0; background: var(--paper); z-index: 4; }
.exit-frame {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
  z-index: 2; transform-origin: 20% 34%;
  transform: scale(calc(1 - min(var(--sc-p, 0), 0.55) * 1.38));
}
.exit-heading {
  position: absolute; z-index: 5; left: var(--sc-gutter); right: var(--sc-gutter);
  bottom: clamp(2.5rem, 12vh, 6rem); max-width: 20ch;
  font-weight: 600; color: var(--ink-on-white);
  font-size: clamp(2rem, 1.4rem + 3.6vw, 4.5rem); line-height: 1.02;
}
.exit-heading--static { position: static; color: var(--ink-on-white); max-width: 20ch; }

/* ---------------------------------------------------------- reservläge -- */
.rm-only { background: var(--sc-canvas); }
.rm-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; }
.rm-section--hero { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(1.5rem,5vw,3rem); }
.rm-section__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
.rm-section__scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(6,10,18,0.85) 0%, rgba(6,10,18,0.35) 45%, transparent 70%); }
.rm-hero-copy { position: relative; z-index: 2; max-width: 40rem; }
.rm-section--window { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-5); background: #05070c; }
.rm-window-stage { position: relative; width: min(92vw, 1200px); aspect-ratio: 3 / 2; overflow: clip; border-radius: 2px; }
.rm-window-stage__photo, .rm-window-mask__fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.rm-window-mask { position: absolute; z-index: 2; overflow: hidden; }
.rm-window-mask__glass { position: absolute; inset: 0; mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.22), rgba(20,14,8,0.3)); }
.rm-section--frame { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-4); background: #05070c; }
.rm-frame { width: min(94vw, 1400px); aspect-ratio: 16 / 9; border: 1px solid color-mix(in oklab, var(--sc-ink) 16%, transparent); }
.rm-caption { font-family: var(--sc-font-text); font-size: var(--sc-t-sm); color: var(--sc-ink-soft); text-align: center; margin: 0; }
.rm-section--exit { background: var(--paper); display: flex; align-items: center; padding: clamp(1.5rem,6vw,4rem); }

@media (max-width: 860px) {
  .hero-title { max-width: 14ch; }
  .exit-heading { max-width: none; }
}

