.reveal-stage {
  background: #05070c;
  /* crossfade progress 0..1 across the opening 35% of the pin, and a
     triangular bump (4t(1-t)) that peaks at its midpoint: a static
     screenshot and a live-rendered iframe never align pixel-perfectly, and a
     brief blur bridges that mismatch instead of showing two overlapping
     images (emil-design-eng: "use blur to mask imperfect transitions"). */
  --xfade: calc(min(var(--sc-p, 0), 0.35) / 0.35);
  --xfade-blur: calc(4 * var(--xfade) * (1 - var(--xfade)) * 6px);
}
.reveal-frozen {
  position: absolute; inset: 0; z-index: 3; pointer-events: none;
  transform-origin: 50.3% 51.5%;
  transform: scale(calc(1 + var(--xfade) * 0.282));
  opacity: calc(1 - var(--xfade));
  filter: blur(var(--xfade-blur));
}
.reveal-frozen__photo, .reveal-frozen__horai { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.reveal-frozen__glass { position: absolute; inset: 0; mix-blend-mode: multiply; opacity: 0.4; background: linear-gradient(180deg, rgba(255,224,170,0.25), rgba(20,14,8,0.35)); }
.reveal-frame {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; z-index: 2;
  opacity: var(--xfade);
  filter: blur(var(--xfade-blur));
}

