.reveal-frame {
  position: absolute; inset: 0; width: 100%; height: 100%; border: 0; z-index: 2;
  opacity: calc(min(var(--sc-p, 0), 0.35) / 0.35);
}

/* -------------------------------------------------------------- akt 4 exit -- */
.exit-stage { background: var(--sc-canvas); overflow: clip; }
.exit-sweep { position: absolute; inset: 0; background: var(--paper); z-index: 4; }
.exit-frame {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
  z-index: 2; transform-origin: 20% 34%;
  transform: scale(calc(1 - min(var(--sc-p, 0), 0.55) * 1.38));
}
.exit-heading {
  position: absolute; z-index: 5; left: var(--sc-gutter); right: var(--sc-gutter);
  bottom: clamp(2.5rem, 12vh, 6rem); max-width: 20ch;
  font-weight: 600; color: var(--ink-on-white);
  font-size: clamp(2rem, 1.4rem + 3.6vw, 4.5rem); line-height: 1.02;
}
.exit-heading--static { position: static; color: var(--ink-on-white); max-width: 20ch; }

/* ---------------------------------------------------------- reservläge -- */
.rm-only { background: var(--sc-canvas); }
.rm-section { position: relative; min-height: 100vh; min-height: 100svh; overflow: clip; }
.rm-section--hero { display: flex; flex-direction: column; justify-content: flex-end; padding: clamp(1.5rem,5vw,3rem); }
.rm-section__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 0; }
.rm-section__scrim { position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, rgba(6,10,18,0.85) 0%, rgba(6,10,18,0.35) 45%, transparent 70%); }
.rm-hero-copy { position: relative; z-index: 2; max-width: 40rem; }
.rm-section--window { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: var(--sc-5); background: #05070c; }
.rm-window-stage { position: relative; width: min(92vw, 1200px); aspect-ratio: 3 / 2; overflow: clip; border-radius: 2px; }
.rm-window-stage__photo, .rm-window-mask__fill { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.rm-window-mask { position: absolute; z-index: 2; overflow: hidden; }
.rm-window-mask__glass { position: absolute; inset: 0; mix-blend-mode: multiply; background: linear-gradient(180deg, rgba(255,224,170,0.22), rgba(20,14,8,0.3)); }
